#requires -version 5.1
<#
OfficeLiteOptimizer.ps1
Stable one-line launcher + embedded optimizer payload.
Run from ordinary Windows PowerShell. It requests UAC automatically when needed.
Canonical command:
  irm https://raw.githubusercontent.com/Abestreid/pc/main/OfficeLiteOptimizer.ps1 | iex
#>

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
$SelfUrl = 'https://raw.githubusercontent.com/Abestreid/pc/main/OfficeLiteOptimizer.ps1'

function Test-OfficeLiteAdmin {
    $id = [Security.Principal.WindowsIdentity]::GetCurrent()
    $p = New-Object Security.Principal.WindowsPrincipal($id)
    return $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

if (-not (Test-OfficeLiteAdmin)) {
    Write-Host 'Requesting administrator rights...' -ForegroundColor Yellow
    $elevatedCommand = @"
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
`$code = (New-Object Net.WebClient).DownloadString('$SelfUrl')
Invoke-Expression `$code
"@
    $encoded = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($elevatedCommand))
    $ps = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    try {
        Start-Process -FilePath $ps -Verb RunAs -ArgumentList "-NoProfile -ExecutionPolicy Bypass -EncodedCommand $encoded" -ErrorAction Stop | Out-Null
        Write-Host 'Confirm UAC. Optimization will continue in the administrator PowerShell window.' -ForegroundColor Green
    }
    catch {
        Write-Error "UAC elevation was cancelled or failed: $($_.Exception.Message)"
    }
    return
}

# Embedded GZip payload keeps this repository to one stable file while preserving the full optimizer.
$payload = ''
$bytes = [Convert]::FromBase64String($payload)
$ms = New-Object IO.MemoryStream(,$bytes)
$gz = New-Object IO.Compression.GZipStream($ms,[IO.Compression.CompressionMode]::Decompress)
$sr = New-Object IO.StreamReader($gz,[Text.Encoding]::UTF8,$true)
$core = $sr.ReadToEnd()
$sr.Dispose(); $gz.Dispose(); $ms.Dispose()

& ([ScriptBlock]::Create($core))
